-- 美工申请 Phase 1：无系统附件。历史 URL 字段仅供兼容读取。
do $$ begin create type public.designer_work_mode as enum ('design_only','design_production','setup_only'); exception when duplicate_object then null; end $$;
do $$ begin create type public.designer_stage_type as enum ('design','production','setup'); exception when duplicate_object then null; end $$;
do $$ begin create type public.designer_stage_status as enum ('unclaimed','scheduled','arranged','in_progress','awaiting_agent_confirmation','revision','completed','cancelled'); exception when duplicate_object then null; end $$;
alter table public.designer_requests add column if not exists creator_profile_id uuid references public.creator_profiles(id) on delete set null, add column if not exists creator_entity_id uuid references public.creator_entities(id) on delete set null, add column if not exists region_id uuid references public.regions(id) on delete set null, add column if not exists work_mode public.designer_work_mode, add column if not exists event_start_at timestamptz, add column if not exists event_end_at timestamptz, add column if not exists color text, add column if not exists style text, add column if not exists specification text, add column if not exists live_room text, add column if not exists reference_material_status text not null default 'not_required' check (reference_material_status in ('not_required','provided'));
create table if not exists public.designer_request_stages (id uuid primary key default gen_random_uuid(), request_id uuid not null references public.designer_requests(id) on delete cascade, stage_type public.designer_stage_type not null, status public.designer_stage_status not null default 'unclaimed', assignee_profile_id uuid references public.profiles(id) on delete set null, assignee_employee_id uuid references public.employees(id) on delete set null, accepted_at timestamptz, submitted_at timestamptz, confirmed_at timestamptz, confirmed_by_profile_id uuid references public.profiles(id) on delete set null, confirmed_by_employee_id uuid references public.employees(id) on delete set null, feedback text, feedback_count integer not null default 0 check(feedback_count>=0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(request_id,stage_type));
create index if not exists designer_request_stages_assignee_idx on public.designer_request_stages(assignee_profile_id,status);
drop trigger if exists set_designer_request_stages_updated_at on public.designer_request_stages; create trigger set_designer_request_stages_updated_at before update on public.designer_request_stages for each row execute function public.set_updated_at();
alter table public.designer_request_stages enable row level security;
create or replace function public.can_access_designer_request(p_request_id uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$ select exists(select 1 from public.designer_requests r where r.id=p_request_id and (r.agent_profile_id=auth.uid() or exists(select 1 from public.designer_request_stages s where s.request_id=r.id and s.assignee_profile_id=auth.uid()) or (r.status='unclaimed' and public.current_user_has_permission('designer-intake','view') and ((r.work_mode is null) or (r.work_mode is not null and r.region_id is not null and public.current_user_can_access_region(r.region_id)))))); $$;
drop policy if exists "Design requests are visible by workflow" on public.designer_requests; create policy "Design requests are visible by scoped workflow" on public.designer_requests for select to authenticated using(agent_profile_id=auth.uid() or designer_profile_id=auth.uid() or (status='unclaimed' and public.current_user_has_permission('designer-intake','view') and ((work_mode is null) or (work_mode is not null and region_id is not null and public.current_user_can_access_region(region_id)))));
drop policy if exists "Agents can create design requests" on public.designer_requests; create policy "Agents can create legacy design requests" on public.designer_requests for insert to authenticated with check(agent_profile_id=auth.uid() and work_mode is null and public.current_user_has_permission('agent-design-requests','use'));
drop policy if exists "Design workflow participants can update requests" on public.designer_requests; create policy "Legacy design request updates only" on public.designer_requests for update to authenticated using(work_mode is null and (agent_profile_id=auth.uid() or designer_profile_id=auth.uid())) with check(work_mode is null and (agent_profile_id=auth.uid() or designer_profile_id=auth.uid()));
create policy "Stage readers are workflow participants" on public.designer_request_stages for select to authenticated using(public.can_access_designer_request(request_id));
create or replace function public.list_designer_request_creators() returns table(id uuid,creator_entity_id uuid,region_id uuid,region_name text,platform public.creator_platform,platform_user_id text,platform_account text,creator_name text,creator_type public.creator_type,manager_employee_id uuid,manager_name text) language sql stable security definer set search_path=public,pg_temp as $$ select cp.id,cp.creator_entity_id,cp.region_id,r.name,cp.platform,cp.platform_user_id,cp.platform_account,cp.creator_name,cp.creator_type,cp.manager_employee_id,coalesce(e.nickname,e.full_name) from public.creator_profiles cp left join public.regions r on r.id=cp.region_id left join public.employees e on e.id=cp.manager_employee_id where public.current_user_has_permission('agent-design-requests','use') and public.current_user_can_access_region(cp.region_id) and cp.status='active' order by cp.creator_name; $$;
create or replace function public.create_designer_request(p_creator_profile_id uuid,p_work_mode public.designer_work_mode,p_request_type public.design_request_type,p_event_start_at timestamptz default null,p_event_end_at timestamptz default null,p_design_content text default null,p_style text default null,p_color text default null,p_specification text default null,p_special_content text default null,p_reference_material_status text default 'not_required',p_live_room text default null) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare c public.creator_profiles; rid uuid; eid uuid; st public.designer_stage_type; begin if not public.current_user_has_permission('agent-design-requests','use') then raise exception 'Permission denied.'; end if; select * into c from public.creator_profiles where id=p_creator_profile_id and status='active'; if c.id is null or not public.current_user_can_access_region(c.region_id) then raise exception 'Creator access denied.'; end if; if p_reference_material_status not in ('not_required','provided') then raise exception 'Invalid reference material status.'; end if; select id into eid from public.employees where profile_id=auth.uid() and deleted_at is null limit 1; insert into public.designer_requests(agent_profile_id,agent_employee_id,creator_profile_id,creator_entity_id,region_id,work_mode,request_type,platform,platform_user_id,creator_name,platform_account,event_start_at,event_end_at,design_content,style,color,specification,special_content,reference_material_status,live_room) values(auth.uid(),eid,c.id,c.creator_entity_id,c.region_id,p_work_mode,p_request_type,c.platform,c.platform_user_id,c.creator_name,c.platform_account,p_event_start_at,p_event_end_at,p_design_content,p_style,p_color,p_specification,p_special_content,p_reference_material_status,p_live_room) returning id into rid; st:=case when p_work_mode='setup_only' then 'setup' else 'design' end; insert into public.designer_request_stages(request_id,stage_type) values(rid,st); if p_work_mode='design_production' then insert into public.designer_request_stages(request_id,stage_type,status) values(rid,'production','scheduled'); end if; return rid; end $$;
create or replace function public.claim_designer_request_stage(p_stage_id uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare s public.designer_request_stages; eid uuid; begin select * into s from public.designer_request_stages where id=p_stage_id for update; if s.status<>'unclaimed' or not public.current_user_has_permission('designer-intake','use') or not public.can_access_designer_request(s.request_id) then raise exception 'Stage unavailable.'; end if; select id into eid from public.employees where profile_id=auth.uid() and deleted_at is null limit 1; update public.designer_request_stages set status=case when s.stage_type='setup' then 'scheduled' else 'in_progress' end,assignee_profile_id=auth.uid(),assignee_employee_id=eid,accepted_at=now() where id=s.id; end $$;
create or replace function public.advance_designer_request_stage(p_stage_id uuid,p_action text) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare s public.designer_request_stages; begin select * into s from public.designer_request_stages where id=p_stage_id for update; if s.assignee_profile_id<>auth.uid() or s.stage_type<>'setup' then raise exception 'Permission denied.'; end if; if p_action='arrange' and s.status='scheduled' then update public.designer_request_stages set status='arranged' where id=s.id; elsif p_action='start' and s.status='arranged' then update public.designer_request_stages set status='in_progress' where id=s.id; else raise exception 'Invalid transition.'; end if; end $$;
create or replace function public.submit_designer_request_stage(p_stage_id uuid,p_feedback text default null) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare s public.designer_request_stages; begin select * into s from public.designer_request_stages where id=p_stage_id for update; if s.assignee_profile_id<>auth.uid() or s.status not in ('in_progress','revision') then raise exception 'Invalid submission.'; end if; update public.designer_request_stages set status='awaiting_agent_confirmation',submitted_at=now(),feedback=coalesce(nullif(btrim(p_feedback),''),feedback) where id=s.id; end $$;
create or replace function public.confirm_designer_request_stage(p_stage_id uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare s public.designer_request_stages; r public.designer_requests; eid uuid; begin select * into s from public.designer_request_stages where id=p_stage_id for update; select * into r from public.designer_requests where id=s.request_id; if r.agent_profile_id<>auth.uid() or s.status<>'awaiting_agent_confirmation' then raise exception 'Confirmation denied.'; end if; select id into eid from public.employees where profile_id=auth.uid() and deleted_at is null limit 1; update public.designer_request_stages set status='completed',confirmed_at=now(),confirmed_by_profile_id=auth.uid(),confirmed_by_employee_id=eid where id=s.id; if s.stage_type='design' and r.work_mode='design_production' then update public.designer_request_stages set status='unclaimed' where request_id=r.id and stage_type='production' and status='scheduled'; else update public.designer_requests set status='completed',completed_at=now() where id=r.id; end if; end $$;
create or replace function public.return_designer_request_stage(p_stage_id uuid,p_feedback text) returns void language plpgsql security definer set search_path=public,pg_temp as $$ declare s public.designer_request_stages; r public.designer_requests; begin if nullif(btrim(p_feedback),'') is null then raise exception 'Feedback is required.'; end if; select * into s from public.designer_request_stages where id=p_stage_id for update; select * into r from public.designer_requests where id=s.request_id; if r.agent_profile_id<>auth.uid() or s.status<>'awaiting_agent_confirmation' then raise exception 'Return denied.'; end if; update public.designer_request_stages set status='revision',feedback=btrim(p_feedback),feedback_count=feedback_count+1 where id=s.id; end $$;
revoke all on function public.can_access_designer_request(uuid) from public;
revoke all on function public.list_designer_request_creators() from public;
revoke all on function public.create_designer_request(uuid,public.designer_work_mode,public.design_request_type,timestamptz,timestamptz,text,text,text,text,text,text,text) from public;
revoke all on function public.claim_designer_request_stage(uuid) from public;
revoke all on function public.advance_designer_request_stage(uuid,text) from public;
revoke all on function public.submit_designer_request_stage(uuid,text) from public;
revoke all on function public.confirm_designer_request_stage(uuid) from public;
revoke all on function public.return_designer_request_stage(uuid,text) from public;
grant execute on function public.can_access_designer_request(uuid),public.list_designer_request_creators() to authenticated;
grant execute on function public.create_designer_request(uuid,public.designer_work_mode,public.design_request_type,timestamptz,timestamptz,text,text,text,text,text,text,text) to authenticated;
grant execute on function public.claim_designer_request_stage(uuid),public.advance_designer_request_stage(uuid,text),public.submit_designer_request_stage(uuid,text),public.confirm_designer_request_stage(uuid),public.return_designer_request_stage(uuid,text) to authenticated;
